def largestPalindromicNumber(digits):
    cnt = [0] * 10
    for ch in digits:
        cnt[ord(ch) - 48] += 1
    half = "".join(str(d) * (cnt[d] // 2) for d in range(9, 0, -1))
    if not half:
        for d in range(9, -1, -1):
            if cnt[d]:
                return str(d)
    half += "0" * (cnt[0] // 2)
    mid = ""
    for d in range(9, -1, -1):
        if cnt[d] % 2:
            mid = str(d)
            break
    return half + mid + half[::-1]
